'use client';
import { useFrame, useThree } from '@react-three/fiber';
import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef } from 'react';
import { AdditiveBlending, BufferAttribute, BufferGeometry, Color, Matrix4, Plane, Raycaster, ShaderMaterial, Sphere, Vector2, Vector3, type Points } from 'three';
import { useQuality } from '../../../three';
import { FORMS, buildForms } from './shapes';
import { fragmentShader, vertexShader } from './shaders';

export interface FieldHandle { pulse(): void }
export interface FieldProps {
  /** Requested particle count before the quality profile's density is applied. */
  count: number;
  /** Target form index (0 sphere, 1 torus, 2 glyph). */
  form: number;
  autoCycle: boolean;
  /** Animate (flow, morphs, pointer, pulse). False = a still frame that still follows every control. */
  animate: boolean;
  intensity: number;
  /** Flow speed; in a still frame it chooses the frozen phase of the flow instead. */
  flow: number;
  /** The field finished a hold and wants the next form (auto-cycle). */
  onAdvance: (next: number) => void;
  /** Effective particle count after quality scaling. */
  onCount?: (n: number) => void;
}

const MORPH_SECONDS = 2.4;
const HOLD_SECONDS = 5;
const PULSE_SECONDS = 1.5;

export const Field = forwardRef<FieldHandle, FieldProps>(function Field({ count, form, autoCycle, animate, intensity, flow, onAdvance, onCount }, ref) {
  const quality = useQuality();
  const gl = useThree((s) => s.gl);
  const invalidate = useThree((s) => s.invalidate);
  const effective = Math.max(600, Math.round((count * quality.density) / 100) * 100);
  const points = useRef<Points>(null);

  const geometry = useMemo(() => {
    const f = buildForms(effective);
    const g = new BufferGeometry();
    g.setAttribute('position', new BufferAttribute(f.sphere, 3));
    g.setAttribute('aSphere', new BufferAttribute(f.sphere, 3));
    g.setAttribute('aTorus', new BufferAttribute(f.torus, 3));
    g.setAttribute('aGlyph', new BufferAttribute(f.glyph, 3));
    g.setAttribute('aSeed', new BufferAttribute(f.seed, 4));
    g.boundingSphere = new Sphere(new Vector3(), 3.5);
    return g;
  }, [effective]);
  useEffect(() => () => geometry.dispose(), [geometry]);
  useEffect(() => { onCount?.(effective); invalidate(); }, [effective, onCount, invalidate]);

  const material = useMemo(() => new ShaderMaterial({
    vertexShader, fragmentShader, transparent: true, depthWrite: false, blending: AdditiveBlending,
    uniforms: {
      uTime: { value: 0 }, uFrom: { value: form }, uTo: { value: form }, uProgress: { value: 1 }, uIntensity: { value: intensity },
      uSize: { value: 2 }, uPixelRatio: { value: 1 }, uPointer: { value: new Vector3(0, 0, 99) }, uPointerStrength: { value: 0 },
      uPulse: { value: new Vector2(0, 0) }, uColorA: { value: new Color('#f3e7d3') }, uColorB: { value: new Color('#ff6a33') }, uAccentShare: { value: 0.14 },
    },
  }), []); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => () => material.dispose(), [material]);

  // Mutable simulation state: never React state (no per-frame re-renders).
  const sim = useRef({ from: form, to: form, progress: 1, hold: 0, time: 0, pulse: -1, pointerAt: -1e9, inside: false, strength: 0, spin: 0 });
  const live = useRef({ animate, autoCycle, onAdvance, flow });
  live.current = { animate, autoCycle, onAdvance, flow };

  useImperativeHandle(ref, () => ({ pulse() { if (live.current.animate) { sim.current.pulse = 0; invalidate(); } } }), [invalidate]);

  // A new target form: morph from whichever form the field is closest to (a cut when animation is off).
  useEffect(() => {
    const s = sim.current;
    if (form === s.to && s.progress >= 1) return;
    if (!animate) { s.from = s.to = form; s.progress = 1; }
    else if (form !== s.to) { s.from = s.progress < 0.5 ? s.from : s.to; s.to = form; s.progress = 0; }
    s.hold = 0;
    invalidate();
  }, [form, animate, invalidate]);
  useEffect(() => {
    const s = sim.current;
    if (!animate) { s.from = s.to; s.progress = 1; s.pulse = -1; s.strength = 0; }
    invalidate();
  }, [animate, invalidate]);
  useEffect(() => { material.uniforms.uIntensity.value = intensity; invalidate(); }, [intensity, material, invalidate]);
  useEffect(() => { if (!animate) { sim.current.time = flow * 6.5; } invalidate(); }, [flow, animate, invalidate]);

  // Pointer / touch presence on the canvas element (R3F keeps the last pointer position after leave).
  useEffect(() => {
    const el = gl.domElement;
    const prevTouch = el.style.touchAction;
    el.style.touchAction = 'none'; // the field reacts to touch drags; the page scrolls outside the stage
    const move = () => { sim.current.pointerAt = performance.now(); sim.current.inside = true; invalidate(); };
    const leave = () => { sim.current.inside = false; invalidate(); };
    el.addEventListener('pointermove', move);
    el.addEventListener('pointerdown', move);
    el.addEventListener('pointerleave', leave);
    el.addEventListener('pointercancel', leave);
    return () => {
      el.style.touchAction = prevTouch;
      el.removeEventListener('pointermove', move); el.removeEventListener('pointerdown', move);
      el.removeEventListener('pointerleave', leave); el.removeEventListener('pointercancel', leave);
    };
  }, [gl, invalidate]);

  const tmp = useMemo(() => ({ ray: new Raycaster(), plane: new Plane(), hit: new Vector3(), n: new Vector3(), inv: new Matrix4() }), []);

  useFrame((state, rawDt) => {
    const s = sim.current, u = material.uniforms;
    const dt = Math.min(rawDt, 1 / 20);
    const { animate: on, autoCycle: cycle, flow: speed } = live.current;
    let busy = false;
    if (on) {
      s.time += dt * (0.25 + speed * 1.15);
      s.spin += dt * 0.06;
      if (s.progress < 1) { s.progress = Math.min(1, s.progress + dt / MORPH_SECONDS); busy = true; if (s.progress >= 1) s.from = s.to; }
      else if (cycle) { s.hold += dt; if (s.hold > HOLD_SECONDS) { s.hold = 0; live.current.onAdvance((s.to + 1) % FORMS.length); } }
      if (s.pulse >= 0) { s.pulse += dt; if (s.pulse > PULSE_SECONDS) s.pulse = -1; busy = true; }
      const want = s.inside && performance.now() - s.pointerAt < 1400 ? 1 : 0;
      s.strength += (want - s.strength) * Math.min(1, dt * (want ? 6 : 2.5));
      if (Math.abs(want - s.strength) > 0.002) busy = true;
    }
    if (points.current) points.current.rotation.y = s.spin;
    // pointer → a point on the plane through the field's centre, facing the camera, in the field's local space
    if (s.strength > 0.001 && points.current) {
      tmp.ray.setFromCamera(state.pointer, state.camera);
      state.camera.getWorldDirection(tmp.n);
      tmp.plane.setFromNormalAndCoplanarPoint(tmp.n, points.current.getWorldPosition(tmp.hit));
      if (tmp.ray.ray.intersectPlane(tmp.plane, tmp.hit)) {
        points.current.updateMatrixWorld();
        (u.uPointer.value as Vector3).copy(tmp.hit).applyMatrix4(tmp.inv.copy(points.current.matrixWorld).invert());
      }
    }
    u.uTime.value = s.time;
    u.uFrom.value = s.from; u.uTo.value = s.to; u.uProgress.value = s.progress;
    u.uPointerStrength.value = s.strength;
    (u.uPulse.value as Vector2).set(Math.max(0, s.pulse), s.pulse >= 0 ? 1 - s.pulse / PULSE_SECONDS : 0);
    u.uPixelRatio.value = gl.getPixelRatio();
    u.uSize.value = 2.1 * Math.sqrt(Math.sqrt(24000 / effective));
    // In a demand loop (paused / reduced) keep drawing only while something is still settling.
    if (busy && state.frameloop === 'demand') invalidate();
  });

  return <points ref={points} geometry={geometry} material={material} frustumCulled={false} />;
});

/**
 * The whole field moves in the vertex shader: the CPU only updates a handful of uniforms per frame.
 * Each particle carries its point on all three forms (aSphere, aTorus, aGlyph) and a random seed vector.
 */
export const vertexShader = /* glsl */ `
attribute vec3 aSphere;
attribute vec3 aTorus;
attribute vec3 aGlyph;
attribute vec4 aSeed;

uniform float uTime;
uniform float uFrom;
uniform float uTo;
uniform float uProgress;
uniform float uIntensity;
uniform float uSize;
uniform float uPixelRatio;
uniform vec3 uPointer;
uniform float uPointerStrength;
uniform vec2 uPulse;

varying float vPick;
varying float vGlow;

vec3 formAt(float i) { return i < 0.5 ? aSphere : (i < 1.5 ? aTorus : aGlyph); }

// Cheap divergence-light swirl: sums of offset sines, phase-shifted per particle.
vec3 flow(vec3 p, float t) {
  float ph = aSeed.w * 6.2831;
  return vec3(
    sin(p.y * 1.7 + t * 0.9 + ph) + sin(p.z * 2.3 - t * 0.6),
    sin(p.z * 1.9 + t * 0.7 + ph * 0.5) + sin(p.x * 2.1 + t * 0.5),
    sin(p.x * 1.5 - t * 0.8 + ph * 0.75) + sin(p.y * 2.6 + t * 0.4)
  ) * 0.5;
}

void main() {
  float stagger = 0.65;
  float p = clamp(uProgress * (1.0 + stagger) - aSeed.x * stagger, 0.0, 1.0);
  p = p * p * (3.0 - 2.0 * p);
  vec3 pos = mix(formAt(uFrom), formAt(uTo), p);
  float flight = sin(p * 3.14159265);
  // mid-flight the particles bloom outwards, then settle onto the new form
  pos += normalize(pos + vec3(1e-4)) * flight * (0.35 + 0.5 * aSeed.y);
  pos += flow(pos * 0.9, uTime) * (0.03 + 0.2 * uIntensity) * (0.7 + flight);

  vec3 d = pos - uPointer;
  float push = uPointerStrength * exp(-dot(d, d) * 2.4);
  pos += normalize(d + vec3(1e-4)) * push * 0.85;

  float ring = exp(-pow(length(pos) - uPulse.x * 3.4, 2.0) * 5.0) * uPulse.y;
  pos += normalize(pos + vec3(1e-4)) * ring * 0.55;

  vec4 mv = modelViewMatrix * vec4(pos, 1.0);
  gl_Position = projectionMatrix * mv;
  float size = uSize * (0.55 + aSeed.y * 0.9) * (1.0 + push * 1.4 + ring * 1.2);
  gl_PointSize = size * uPixelRatio * (6.0 / max(0.5, -mv.z));
  vPick = aSeed.z;
  vGlow = clamp(0.45 + 0.55 * uIntensity + push * 0.6 + ring, 0.0, 1.6);
}
`;

export const fragmentShader = /* glsl */ `
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform float uAccentShare;
varying float vPick;
varying float vGlow;

void main() {
  vec2 c = gl_PointCoord - 0.5;
  float r = length(c);
  if (r > 0.5) discard;
  float a = smoothstep(0.5, 0.05, r);
  vec3 col = vPick > 1.0 - uAccentShare ? uColorB : uColorA;
  gl_FragColor = vec4(col * vGlow, a * 0.85);
  #include <colorspace_fragment>
}
`;

/**
 * Target forms for the particle field. Deterministic (seeded): the same count always yields the same points.
 * Every particle owns one point on each form, so a morph is a per-particle interpolation done in the vertex shader.
 */
export const FORMS = [
  { id: 'sphere', name: 'Sphere', note: 'A Fibonacci lattice on a sphere: evenly spaced, no poles.' },
  { id: 'torus', name: 'Torus', note: 'Uniform samples on a tilted ring.' },
  { id: 'glyph', name: 'Glyph', note: 'An abstract mark: a ring crossed by a stroke, a tick and a dot.' },
] as const;
export type FormId = (typeof FORMS)[number]['id'];
export const formIndex = (id: FormId): number => FORMS.findIndex((f) => f.id === id);

function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const gauss = (r: () => number) => Math.sqrt(-2 * Math.log(Math.max(1e-9, r()))) * Math.cos(2 * Math.PI * r());

type Stroke = { kind: 'line'; a: [number, number]; b: [number, number]; w: number } | { kind: 'arc'; c: [number, number]; r: number; from: number; to: number; w: number } | { kind: 'dot'; c: [number, number]; r: number };
const GLYPH: Stroke[] = [
  { kind: 'arc', c: [-0.1, 0.05], r: 1.2, from: 0.35, to: Math.PI * 2 - 0.15, w: 0.09 },
  { kind: 'line', a: [-1.65, -1.35], b: [1.55, 1.45], w: 0.1 },
  { kind: 'line', a: [-1.45, 1.05], b: [-0.85, 1.05], w: 0.07 },
  { kind: 'dot', c: [1.02, -0.98], r: 0.26 },
];
const strokeLength = (s: Stroke): number => (s.kind === 'line' ? Math.hypot(s.b[0] - s.a[0], s.b[1] - s.a[1]) : s.kind === 'arc' ? s.r * (s.to - s.from) : Math.PI * s.r * 1.6);

export interface FormBuffers { sphere: Float32Array; torus: Float32Array; glyph: Float32Array; seed: Float32Array }

export function buildForms(count: number): FormBuffers {
  const r = rng(0x5eed + count);
  const sphere = new Float32Array(count * 3), torus = new Float32Array(count * 3), glyph = new Float32Array(count * 3), seed = new Float32Array(count * 4);
  const golden = Math.PI * (3 - Math.sqrt(5));
  const tilt = 1.02, ct = Math.cos(tilt), st = Math.sin(tilt);
  const lengths = GLYPH.map(strokeLength), total = lengths.reduce((a, b) => a + b, 0);
  for (let i = 0; i < count; i++) {
    // sphere: Fibonacci lattice, thin shell
    const y = 1 - (i / Math.max(1, count - 1)) * 2, rad = Math.sqrt(1 - y * y), th = golden * i;
    const R = 1.62 + gauss(r) * 0.035;
    sphere.set([Math.cos(th) * rad * R, y * R, Math.sin(th) * rad * R], i * 3);
    // torus: area-uniform (rejection on the minor angle), tilted towards the viewer
    const Rm = 1.32, rm = 0.5;
    let v = 0;
    for (let k = 0; k < 8; k++) { v = r() * Math.PI * 2; if (r() < (Rm + rm * Math.cos(v)) / (Rm + rm)) break; }
    const u = r() * Math.PI * 2, rr = rm + gauss(r) * 0.02;
    const tx = (Rm + rr * Math.cos(v)) * Math.cos(u), tz = (Rm + rr * Math.cos(v)) * Math.sin(u), ty = rr * Math.sin(v);
    torus.set([tx, ty * ct - tz * st, ty * st + tz * ct], i * 3);
    // glyph: strokes sampled by length, with thickness and a little depth
    let pick = r() * total, s = GLYPH[0];
    for (let k = 0; k < GLYPH.length; k++) { if (pick <= lengths[k]) { s = GLYPH[k]; break; } pick -= lengths[k]; }
    let gx = 0, gy = 0;
    if (s.kind === 'line') { const t = r(); gx = s.a[0] + (s.b[0] - s.a[0]) * t + gauss(r) * s.w * 0.5; gy = s.a[1] + (s.b[1] - s.a[1]) * t + gauss(r) * s.w * 0.5; }
    else if (s.kind === 'arc') { const a = s.from + (s.to - s.from) * r(), rr2 = s.r + gauss(r) * s.w * 0.5; gx = s.c[0] + Math.cos(a) * rr2; gy = s.c[1] + Math.sin(a) * rr2; }
    else { const a = r() * Math.PI * 2, d = Math.sqrt(r()) * s.r; gx = s.c[0] + Math.cos(a) * d; gy = s.c[1] + Math.sin(a) * d; }
    glyph.set([gx, gy, gauss(r) * 0.08], i * 3);
    // x: morph stagger, y: size, z: colour pick, w: flow phase
    seed.set([r(), r(), r(), r()], i * 4);
  }
  return { sphere, torus, glyph, seed };
}

/* Drift — an always-dark instrument: hairline rules, mono readouts, one ember accent. */
.root { min-height: 100%; }

.stage {
  position: relative;
  overflow: hidden;
  width: 100%;
  aspect-ratio: 1 / 1;
  max-height: 72svh;
  border: 1px solid var(--mk-line, #f3f0e826);
  border-radius: var(--mk-radius-m, 10px);
  background:
    radial-gradient(60% 55% at 50% 48%, #1c1a16 0%, #0e0e0c 70%),
    #0e0e0c;
  touch-action: none;
}
@container (width >= 44rem) { .stage { aspect-ratio: 4 / 3; } }
.stage::after {
  /* survey ticks along the edges: a quiet frame of reference for scale */
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(90deg, #f3f0e81f 0 1px, transparent 1px 40px) top / 100% 6px no-repeat,
    repeating-linear-gradient(90deg, #f3f0e81f 0 1px, transparent 1px 40px) bottom / 100% 6px no-repeat,
    repeating-linear-gradient(0deg, #f3f0e81f 0 1px, transparent 1px 40px) left / 6px 100% no-repeat,
    repeating-linear-gradient(0deg, #f3f0e81f 0 1px, transparent 1px 40px) right / 6px 100% no-repeat;
}
.formName {
  position: absolute;
  left: 16px;
  bottom: 10px;
  margin: 0;
  pointer-events: none;
  font-family: var(--mk-font-serif, Georgia, serif);
  font-style: italic;
  font-size: clamp(1.8rem, 6cqi, 3rem);
  line-height: 1;
  color: var(--mk-ink, #f3f0e8);
}

.panel {
  display: grid;
  align-content: start;
  gap: 16px;
  min-width: 0;
  padding: 16px;
  border: 1px solid var(--mk-line, #f3f0e826);
  border-radius: var(--mk-radius-m, 10px);
  background: var(--mk-surface, #171714);
}
.choice {
  display: grid;
  place-items: center;
  min-height: 40px;
  padding: 0 8px;
  border: 1px solid var(--mk-line, #f3f0e826);
  border-radius: var(--mk-radius-s, 4px);
  font-size: 13.5px;
  cursor: pointer;
}
.choice:hover { border-color: var(--mk-line-strong, #f3f0e8); }
.choice:has(input:checked) { background: var(--mk-ink, #f3f0e8); color: var(--mk-bg, #0e0e0c); border-color: var(--mk-ink, #f3f0e8); }
.choice:has(input:focus-visible) { outline: 2px solid var(--mk-focus, #8ab4ff); outline-offset: 2px; }
.check { width: 16px; height: 16px; accent-color: var(--mk-signal, #ff5a2b); }
.range { width: 100%; min-height: 24px; accent-color: var(--mk-signal, #ff5a2b); }
.select {
  min-height: 38px;
  padding: 0 10px;
  border: 1px solid var(--mk-line-strong, #f3f0e8);
  border-radius: var(--mk-radius-s, 4px);
  background: var(--mk-bg, #0e0e0c);
  color: var(--mk-ink, #f3f0e8);
  font: inherit;
  font-size: 13.5px;
}
.btn {
  min-height: 40px;
  min-width: 88px;
  padding: 0 16px;
  border: 1px solid var(--mk-line-strong, #f3f0e8);
  border-radius: 999px;
  background: transparent;
  color: var(--mk-ink, #f3f0e8);
  font-size: 13.5px;
}
.btn:first-child { background: var(--mk-ink, #f3f0e8); color: var(--mk-bg, #0e0e0c); }
.btn:hover:not(:disabled) { border-color: var(--mk-signal, #ff5a2b); }
.btn:disabled { color: var(--mk-ink-muted, #a8a59a); border-color: var(--mk-line, #f3f0e826); background: transparent; cursor: not-allowed; }
